import sqlite3
import hashlib
import os
import time
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = os.urandom(32)

DB_PATH = '/var/data/users.db'

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    conn.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        last_login REAL
    )''')
    conn.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        owner_id INTEGER,
        title TEXT,
        content TEXT,
        classification TEXT DEFAULT 'internal',
        FOREIGN KEY(owner_id) REFERENCES users(id)
    )''')
    conn.commit()
    conn.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        conn = get_db()
        user = conn.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
        conn.close()
        if not user:
            return jsonify({'error': 'Invalid API key'}), 401
        request.current_user = user
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents/search', methods=['GET'])
@require_auth
def search_documents():
    """Search documents by title. Supports filtering by classification."""
    query = request.args.get('q', '')
    classification = request.args.get('classification', 'internal')
    owner_filter = request.args.get('owner', '')

    # Build search query with owner filter
    sql = "SELECT d.id, d.title, d.classification, u.username as owner FROM documents d JOIN users u ON d.owner_id = u.id WHERE d.classification = '" + classification + "'"

    if query:
        sql += " AND d.title LIKE '" + query + "'"

    if owner_filter:
        sql += " AND u.username = '" + owner_filter + "'"

    # Apply row-level access control
    current_user = request.current_user
    if current_user['role'] != 'admin':
        sql += " AND (d.owner_id = " + str(current_user['id']) + " OR d.classification != 'restricted')"

    conn = get_db()
    try:
        results = conn.execute(sql).fetchall()
        documents = [{'id': r['id'], 'title': r['title'], 
                     'classification': r['classification'],
                     'owner': r['owner']} for r in results]
    except sqlite3.OperationalError as e:
        conn.close()
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 400

    conn.close()
    return jsonify({'results': documents, 'count': len(documents)})

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    """Retrieve full document content by ID."""
    conn = get_db()
    doc = conn.execute('SELECT d.*, u.username as owner FROM documents d JOIN users u ON d.owner_id = u.id WHERE d.id = ?', (doc_id,)).fetchone()
    conn.close()

    if not doc:
        return jsonify({'error': 'Not found'}), 404

    current_user = request.current_user
    if doc['classification'] == 'restricted' and current_user['role'] != 'admin' and doc['owner_id'] != current_user['id']:
        return jsonify({'error': 'Access denied'}), 403

    return jsonify({'id': doc['id'], 'title': doc['title'],
                   'content': doc['content'], 'classification': doc['classification'],
                   'owner': doc['owner']})

@app.route('/api/users/profile', methods=['GET'])
@require_auth
def get_profile():
    user = request.current_user
    return jsonify({'id': user['id'], 'username': user['username'], 
                   'role': user['role']})

@app.route('/api/admin/users', methods=['GET'])
@require_auth
def list_users():
    if request.current_user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    conn = get_db()
    users = conn.execute('SELECT id, username, role, last_login FROM users').fetchall()
    conn.close()
    return jsonify({'users': [dict(u) for u in users]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
